import assert from 'node:assert/strict';
import {randomBytes,randomUUID,createHash} from 'node:crypto';
import {createGenerationSessionCustody,GENERATION_SESSION_RECORD_SQL} from '../../../lib/generation-session-custody.mjs';
import {generationCoordinatorScopeDigest} from '../../../lib/generation-family-stages.mjs';
import {createDeletionJournal} from '../kakei-completion/lib/shared-deletion-journal.mjs';
export async function verifyGenerationSessionCustody({admin,coordinator,transaction,scope,options,retention,originals,handoff,port:familyStages,handlers}){
 assert.ok((await admin.query("select to_regclass('maintenance_private.generation_session_custody') relation")).rows[0].relation,'Install exact new schema BEFORE generation catalog is frozen; never retrofit old catalog digest');
 const ids=(await admin.query('select id from auth.sessions where user_id=$1 order by id',[scope.userID])).rows.map(r=>r.id),digest=createHash('sha256').update(JSON.stringify(ids)).digest('hex');
 const proof={domain:'SharedAccount/generation-session-coverage/v1',scopeDigest:generationCoordinatorScopeDigest(scope),generationID:options.generationID,nativeLease:options.nativeLease,authSessionsDigest:digest,apps:scope.apps.map(a=>({...a,sessionDigest:digest,originalsDigest:'b'.repeat(64),writerCoverageDigest:'a'.repeat(64)}))};let coverageLive=true,late=false,contact=false;
 const opts={...options,retention,originals,handoff,familyStages,verifySessionCoverage:async()=>coverageLive?structuredClone(proof):null},port=createGenerationSessionCustody(opts),stage='verify-sessions-before',args=[options.generationID,JSON.stringify(scope),options.nativeLease,JSON.stringify(options.homes)];
 const journal=createDeletionJournal({transaction:work=>transaction(coordinator,async tx=>{const result=await work(tx);if(late)coverageLive=false;if(contact)throw Error('synthetic last contact refusal');return result;})},{...handlers,...port.handlers});
 const snap=async()=>({native:(await admin.query('select * from maintenance_private.account_deletion_requests where id=$1',[scope.apps.find(a=>a.app==='ouchi-maintenance').requestID])).rows,prep:(await admin.query('select * from maintenance_private.family_native_preparations where generation_id=$1',[options.generationID])).rows,handoff:(await admin.query('select * from maintenance_private.generation_family_handoffs where generation_id=$1',[options.generationID])).rows,originals:(await admin.query('select * from maintenance_private.generation_family_originals where generation_id=$1 order by home_id,actor_id',[options.generationID])).rows,family:(await admin.query('select * from maintenance_private.generation_stage_custody where generation_id=$1',[options.generationID])).rows});
 const before=await snap(),root=(await admin.query('select * from private.kb_shared_deletion_journal where request_id=$1',[scope.requestID])).rows[0],count=async()=> (await admin.query('select count(*)::int n from maintenance_private.generation_session_custody where generation_id=$1',[options.generationID])).rows[0].n;
 const exactReceipt={...root.scope,durable:true,stage};
 await assert.rejects(transaction(coordinator,tx=>tx.query('update private.kb_shared_deletion_journal set receipts=receipts||$2::jsonb where request_id=$1',[scope.requestID,{[stage]:exactReceipt}])),/Exact ordered generation|Exact new generation/,'Bare fourth receipt never accepted');
 await assert.rejects(transaction(coordinator,async tx=>{assert.equal((await tx.query(GENERATION_SESSION_RECORD_SQL,[...args,proof,'c'.repeat(64)])).rows[0].ok,true);}),/Exact fourth session receipt/,'Raw witness without root receipt cannot COMMIT');assert.equal(await count(),0);
 coverageLive=false;await assert.rejects(journal.perform(scope,stage),/ALL owner/);coverageLive=true;
 late=true;await assert.rejects(journal.perform(scope,stage),/Current transaction verification/);late=false;coverageLive=true;assert.equal(await count(),0);assert.deepEqual(await snap(),before);
 contact=true;await assert.rejects(journal.perform(scope,stage),/last contact/);contact=false;assert.equal(await count(),0);assert.deepEqual((await admin.query('select * from private.kb_shared_deletion_journal where request_id=$1',[scope.requestID])).rows[0],root);
 const unexpected=randomUUID();await admin.query("insert into auth.sessions(id,user_id,created_at,updated_at,aal) values($1,$2,now(),now(),'aal1')",[unexpected,scope.userID]);await assert.rejects(journal.perform(scope,stage),/session frame/);await admin.query('delete from auth.sessions where id=$1',[unexpected]);assert.equal(await count(),0,'New owner Auth session cannot inherit old generation');
 const wrong=createGenerationSessionCustody({...opts,verifySessionCoverage:async()=>({...proof,apps:[]})});await assert.rejects(transaction(coordinator,tx=>wrong.handlers[stage](scope,tx)),/ALL owner/);assert.equal(await count(),0);
 let lost=true;const lostJournal=createDeletionJournal({transaction:async work=>{const value=await transaction(coordinator,work);if(lost){lost=false;throw Error('synthetic COMMIT acknowledgement lost');}return value;}},{...handlers,...port.handlers});
 await assert.rejects(lostJournal.perform(scope,stage),/COMMIT acknowledgement lost/);assert.equal(await count(),1);
 const saved=(await admin.query('select * from maintenance_private.generation_session_custody where generation_id=$1',[options.generationID])).rows;
 const fact=await transaction(coordinator,tx=>port.readHistorical(scope,tx));assert.equal(fact.sessionCount,ids.length);assert.equal(fact.originalCount,options.homes.length*2);
 assert.deepEqual(await snap(),before,'ZERO native delta: original before/after native/handoff/retention/family custody preserved');
 assert.equal((await admin.query('select count(*)::int n from maintenance_private.deletion_receipt_sessions where request_id=$1',[scope.apps.find(a=>a.app==='ouchi-maintenance').requestID])).rows[0].n,0);
 assert.equal((await admin.query('select receipt_sessions_captured from maintenance_private.account_deletion_requests where id=$1',[scope.apps.find(a=>a.app==='ouchi-maintenance').requestID])).rows[0].receipt_sessions_captured,false);
 assert.equal(await transaction(coordinator,tx=>originals.verifyProcessingOriginal(scope,tx)),true);
 await journal.perform(scope,stage);assert.deepEqual((await admin.query('select * from maintenance_private.generation_session_custody where generation_id=$1',[options.generationID])).rows,saved,'Replay preserves signature, original expiry and producer');
 await assert.rejects(transaction(coordinator,tx=>createGenerationSessionCustody({...opts,key:randomBytes(32)}).readHistorical(scope,tx)),/HMAC/);
 await assert.rejects(coordinator.query('select * from maintenance_private.generation_session_custody'),/permission denied/);
 await assert.rejects(transaction(coordinator,tx=>tx.query('update private.kb_shared_deletion_journal set receipts=receipts||$2::jsonb where request_id=$1',[scope.requestID,{unexpected:exactReceipt}])),/Exact ordered generation|Exact new generation|Exact fourth/);
 const nativeID=scope.apps.find(a=>a.app==='ouchi-maintenance').requestID;
 assert.equal((await admin.query('select public.capture_maintenance_deletion_receipt_sessions($1,$2,$3,$4) ok',[nativeID,scope.userID,scope.apps.find(a=>a.app==='ouchi-maintenance').scopeID,options.nativeLease])).rows[0].ok,false,'Canonical records-erased prerequisite remains unchanged');
 console.log('Generation session fourth checkpoint: whole original Auth session set + actual Ouchi app subset + immutable SAME family-original HMAC custody, real normal journal fourth receipt and zero native/child delta. Bare/partial/late-contact/coverage/new-session refused, lost real COMMIT reply recovers same signed metadata fact; repeated capture does not renew originals. No logout/erase/postAuth/COMPLETE authority; all-app/writer coverage is mandatory synthetic provider here.');
 return {afterLogout:async()=>{coverageLive=false;assert.equal(await transaction(coordinator,tx=>originals.verifyProcessingOriginal(scope,tx)),false);assert.deepEqual(await transaction(coordinator,tx=>port.readHistorical(scope,tx)),fact,'Historical signed session fact remains after real GoTrue logout, never current authority');assert.deepEqual((await admin.query('select * from maintenance_private.generation_session_custody where generation_id=$1',[options.generationID])).rows,saved);}};
}
